function shell(content,{bg="shop_chatgpt_v01",owner=null,ownerLine="",hint="",cls=""}={}){return '<div class="game" style="--bg:url('+art.bg(bg)+')">'+hud()+'<main class="stage '+cls+(owner?' with-owner':'')+'">'+(owner?pic(art.owner(owner),"owner-stand",tx("owner.name"))+(ownerLine?'<div class="owner-bubble">'+ownerLine+'</div>':''):'')+content+'</main>'+(hint?'<footer class="hintbar">'+hint+'</footer>':'')+'</div>';}
