function titlePage(){const title=tx("title.name"),canContinue=savedGameExists||!storageReadAvailable,continueHint=!storageReadAvailable?tx("title.saveReadUnavailable"):!savedGameExists?tx("title.noSaveTitle"):"";return '<main class="title-screen title-v2 title-v4" style="--bg:url('+art.bg("title_riverside_chatgpt_v01")+')">'+pic(art.ownerFull("casual"),"kat-owner",tx("title.ownerAlt"))+'<div class="kat-dish"><div class="kat-plate"></div>'+pic(art.dish,"kat-dish-img",tx("title.dishAlt"))+'<i class="steam s1"></i><i class="steam s2"></i><i class="steam s3"></i></div>'+'<header class="kat-logo"><div class="kat-badge">'+tx("title.badge")+'</div><h1 class="kat-title" data-text="'+title+'">'+title+'</h1><div class="kat-sub"><span>〜</span>'+tx("title.subtitle")+'<span>〜</span></div></header>'+'<nav class="kat-menu">'+btn("🧑‍🍳 "+tx("title.start"),"new",'class="primary"')+btn("📂 "+tx("title.continue"),"continue",canContinue?(continueHint?'class="secondary" title="'+continueHint+'" aria-describedby="title-continue-help"':'class="secondary"'):'class="secondary" disabled title="'+continueHint+'" aria-describedby="title-continue-help"')+(!canContinue||!storageReadAvailable?'<small id="title-continue-help" class="title-no-save disabled-reason">'+continueHint+'</small>':"")+btn("📖 "+tx("title.tutorial"),"help",'class="secondary"')+btn("⚙️ "+tx("title.settings"),"settings",'class="secondary"')+btn("ⓘ "+tx("title.credits"),"credits",'class="secondary"')+'</nav><p class="kat-note">'+tx("title.firstHint")+'</p><footer class="kat-footer"><span>💡 '+tx("title.hint")+'</span><span>'+tx("title.prototypeVersion")+' ／ '+tx("title.prototype")+'</span></footer></main>'; }
