function migrateSave(raw){
 if(!raw||typeof raw!=="object"||Array.isArray(raw))return raw;
 const next=JSON.parse(JSON.stringify(raw));
 if(next.day>1&&["RESULT","UPGRADE"].includes(next.phase))next.remainingArrivals=0;
 const stageInput=next.cookingSession?.stageInput;
 if(stageInput&&!Object.hasOwn(stageInput,"timerStopped"))stageInput.timerStopped=stageInput.elapsedSeconds>0&&!stageInput.timerStarted;
 if(Array.isArray(next.orders))for(const order of next.orders)if(order&&typeof order==="object"&&!Object.hasOwn(order,"qualityBreakdown"))order.qualityBreakdown=null;
 if(!Object.hasOwn(next,"reactionStage"))next.reactionStage=next.phase==="REACTION"?"resultVisible":null;
 if(next.cookingSession?.stageInput&&!Object.hasOwn(next.cookingSession.stageInput,"selectedComponentId"))next.cookingSession.stageInput.selectedComponentId=null;
 if(!Object.hasOwn(next,"activeStoryEventId"))next.activeStoryEventId=null;
 if(next.activeStoryEventId&&!storyEvents.some(event=>event.id===next.activeStoryEventId)){
  if(Array.isArray(next.seenStoryEventIds)&&!next.seenStoryEventIds.includes(next.activeStoryEventId))next.seenStoryEventIds.push(next.activeStoryEventId);
  next.activeStoryEventId=null;
 }
 if(next.activeStoryEventId)next.overlay={kind:"EVENT",eventId:next.activeStoryEventId};
 else if(next.overlay?.kind==="EVENT")next.overlay=null;
 if(!Object.hasOwn(next,"tutorialStep")){
  if(next.day===1){
   if(next.phase==="MORNING")next.tutorialStep=2;
   else if(next.phase==="OPEN")next.tutorialStep=next.tutorialFirstServed?0:3;
   else if(next.phase==="COOK")next.tutorialStep=Math.min(9,4+(next.cookingSession?.stageIndex||0));
   else if(next.phase==="REACTION")next.tutorialStep=next.tutorialFirstServed?0:10;
   else next.tutorialStep=11;
  }else next.tutorialStep=0;
 }
 return next;
}
