const commit=()=>{if(!mainReady||!backupReady)return;const previous=inspectStoredSave(mainReq.result),backup=backupReq.result;if(previous.value&&!previous.errors.length)store.put(previous.value,"backup");else if(backup===undefined)store.put(snapshot,"backup");store.put(snapshot,"main");};
